def get_resource_path(relative_name):
    """PyInstaller _MEIPASS veya calisma dizininden kaynak dosya yolunu dondurur."""
    if hasattr(sys, "_MEIPASS"):
        return os.path.join(sys._MEIPASS, relative_name)
    return os.path.join(os.path.dirname(os.path.abspath(__file__)), relative_name)

EMBEDDED_LOGO_B64 = """"""

def get_app_logo_image(width=44, height=44):
    """
    BonCore kurumsal logosunu (sitedeki logo.png ile ayni) yukler ve yeniden boyutlandirir.
    """
    img = None
    # 1. Dosya yollarini dene
    candidates = [
        get_resource_path("app_logo.png"),
        os.path.join(EXE_DIR, "app_logo.png"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "app_logo.png"),
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "frontend", "public", "logo.png"),
        r"C:\Users\Administrator\Documents\BonCore\frontend\public\logo.png"
    ]
    for p in candidates:
        if os.path.exists(p):
            try:
                img = Image.open(p).convert("RGBA")
                break
            except Exception:
                pass

    # 2. Gomulu Base64 verisinden yukle
    if img is None and EMBEDDED_LOGO_B64:
        try:
            raw = base64.b64decode(EMBEDDED_LOGO_B64)
            img = Image.open(io.BytesIO(raw)).convert("RGBA")
        except Exception:
            pass

    # 3. Son care basit ikon uret
    if img is None:
        img = Image.new("RGBA", (width, height), (16, 185, 129, 255))
        d = ImageDraw.Draw(img)
        d.text((width // 4, height // 4), "B", fill=(255, 255, 255, 255))
        return img

    if img.size != (width, height):
        img = img.resize((width, height), Image.Resampling.LANCZOS)
    return img

