def _enum_windows_ipv4_adapters():
    """Windows GetAdaptersAddresses ile aktif IPv4 ag arayuzlerini dondurur."""
    adapters = []
    if sys.platform != "win32":
        return adapters
    try:
        class SOCKADDR_IN(ctypes.Structure):
            _fields_ = [
                ("sin_family", ctypes.c_ushort),
                ("sin_port", ctypes.c_ushort),
                ("sin_addr", ctypes.c_byte * 4),
                ("sin_zero", ctypes.c_char * 8),
            ]

        class SOCKET_ADDRESS(ctypes.Structure):
            _fields_ = [("lpSockaddr", ctypes.c_void_p), ("iSockaddrLength", ctypes.c_int)]

        class IP_ADAPTER_UNICAST_ADDRESS(ctypes.Structure):
            pass

        IP_ADAPTER_UNICAST_ADDRESS._fields_ = [
            ("Length", wintypes.ULONG),
            ("Flags", wintypes.DWORD),
            ("Next", ctypes.POINTER(IP_ADAPTER_UNICAST_ADDRESS)),
            ("Address", SOCKET_ADDRESS),
            ("PrefixOrigin", ctypes.c_int),
            ("SuffixOrigin", ctypes.c_int),
            ("DadState", ctypes.c_int),
            ("ValidLifetime", wintypes.ULONG),
            ("PreferredLifetime", wintypes.ULONG),
            ("LeaseLifetime", wintypes.ULONG),
            ("OnLinkPrefixLength", ctypes.c_ubyte),
        ]

        class IP_ADAPTER_GATEWAY_ADDRESS(ctypes.Structure):
            pass

        IP_ADAPTER_GATEWAY_ADDRESS._fields_ = [
            ("Length", wintypes.ULONG),
            ("Reserved", wintypes.DWORD),
            ("Next", ctypes.POINTER(IP_ADAPTER_GATEWAY_ADDRESS)),
            ("Address", SOCKET_ADDRESS),
        ]

        class IP_ADAPTER_ADDRESSES(ctypes.Structure):
            pass

        IP_ADAPTER_ADDRESSES._fields_ = [
            ("Length", wintypes.ULONG),
            ("IfIndex", wintypes.DWORD),
            ("Next", ctypes.POINTER(IP_ADAPTER_ADDRESSES)),
            ("AdapterName", ctypes.c_char_p),
            ("FirstUnicastAddress", ctypes.POINTER(IP_ADAPTER_UNICAST_ADDRESS)),
            ("FirstAnycastAddress", ctypes.c_void_p),
            ("FirstMulticastAddress", ctypes.c_void_p),
            ("FirstDnsServerAddress", ctypes.c_void_p),
            ("DnsSuffix", ctypes.c_wchar_p),
            ("Description", ctypes.c_wchar_p),
            ("FriendlyName", ctypes.c_wchar_p),
            ("PhysicalAddress", ctypes.c_ubyte * 8),
            ("PhysicalAddressLength", wintypes.DWORD),
            ("Flags", wintypes.DWORD),
            ("Mtu", wintypes.DWORD),
            ("IfType", wintypes.DWORD),
            ("OperStatus", ctypes.c_int),
            ("Ipv6IfIndex", wintypes.DWORD),
            ("ZoneIndices", wintypes.DWORD * 16),
            ("FirstPrefix", ctypes.c_void_p),
            ("TransmitLinkSpeed", ctypes.c_uint64),
            ("ReceiveLinkSpeed", ctypes.c_uint64),
            ("FirstWinsServerAddress", ctypes.c_void_p),
            ("FirstGatewayAddress", ctypes.POINTER(IP_ADAPTER_GATEWAY_ADDRESS)),
        ]

        iphlpapi = ctypes.WinDLL("iphlpapi")
        GAA_FLAG_INCLUDE_GATEWAYS = 0x0080
        buf_len = wintypes.ULONG(32768)
        buf = ctypes.create_string_buffer(buf_len.value)
        ret = iphlpapi.GetAdaptersAddresses(
            socket.AF_INET,
            GAA_FLAG_INCLUDE_GATEWAYS,
            None,
            ctypes.cast(buf, ctypes.POINTER(IP_ADAPTER_ADDRESSES)),
            ctypes.byref(buf_len),
        )
        if ret == 111:
            buf = ctypes.create_string_buffer(buf_len.value)
            ret = iphlpapi.GetAdaptersAddresses(
                socket.AF_INET,
                GAA_FLAG_INCLUDE_GATEWAYS,
                None,
                ctypes.cast(buf, ctypes.POINTER(IP_ADAPTER_ADDRESSES)),
                ctypes.byref(buf_len),
            )
        if ret != 0:
            return adapters

        addr = ctypes.cast(buf, ctypes.POINTER(IP_ADAPTER_ADDRESSES))
        while addr:
            cur = addr.contents
            if cur.OperStatus == 1:
                friendly = cur.FriendlyName or ""
                desc = cur.Description or ""
                has_gw = bool(cur.FirstGatewayAddress)
                if_type = int(cur.IfType)
                u = cur.FirstUnicastAddress
                while u:
                    sa = u.contents.Address
                    if sa.lpSockaddr and sa.iSockaddrLength >= 16:
                        sin = ctypes.cast(sa.lpSockaddr, ctypes.POINTER(SOCKADDR_IN)).contents
                        if sin.sin_family == socket.AF_INET:
                            ip_str = socket.inet_ntoa(bytes(sin.sin_addr))
                            adapters.append({
                                "ip": ip_str,
                                "if_type": if_type,
                                "has_gw": has_gw,
                                "name": f"{friendly} {desc}".lower(),
                                "prefix_len": int(u.contents.OnLinkPrefixLength or 24),
                            })
                    u = u.contents.Next
            addr = cur.Next
    except Exception:
        pass
    return adapters

def _udp_route_probe(host: str, port: int = 80):
    sock = None
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        sock.settimeout(0.5)
        sock.connect((host, int(port)))
        return sock.getsockname()[0]
    except Exception:
        return None
    finally:
        if sock:
            try:
                sock.close()
            except Exception:
                pass

def _is_valid_host_ip(ip_str: str) -> bool:
    try:
        addr = ipaddress.IPv4Address(ip_str)
        return not (addr.is_loopback or addr.is_link_local or addr.is_unspecified or addr.is_multicast)
    except Exception:
        return False

def get_local_ip(preferred_peer_ip: str = None, preferred_peer_port: int = 2004):
    """
    Kasa bilgisayarinin gercek yerel LAN IPv4 adresini tespit eder.
    VPN/sanal adaptorleri (WireGuard, Tailscale, Hyper-V, VirtualBox, CGNAT vb.)
    eler; terazi alt agindaki fiziksel Ethernet/Wi-Fi arayuzunu onceliklendirir.
    """
    peer_ip = (preferred_peer_ip or "").strip()
    peer_probe_ip = _udp_route_probe(peer_ip, preferred_peer_port) if _is_valid_host_ip(peer_ip) else None
    inet_probe_ip = _udp_route_probe("8.8.8.8", 80) or _udp_route_probe("1.1.1.1", 80)

    cgnat_net = ipaddress.IPv4Network("100.64.0.0/10")
    peer_octets = peer_ip.split(".") if _is_valid_host_ip(peer_ip) else []

    adapters = _enum_windows_ipv4_adapters()
    best_ip = None
    best_score = -10**9

    for item in adapters:
        ip_str = item["ip"]
        if not _is_valid_host_ip(ip_str):
            continue
        addr = ipaddress.IPv4Address(ip_str)
        score = 0
        if_type = item["if_type"]
        lname = item["name"]
        is_virtual = (if_type in (24, 131)) or any(k in lname for k in _VIRTUAL_ADAPTER_KEYWORDS)

        if if_type in (6, 71) and not is_virtual:
            score += 60
        elif not is_virtual:
            score += 20
        else:
            score -= 90

        if item["has_gw"]:
            score += 30
        if addr in cgnat_net:
            score -= 60

        octets = ip_str.split(".")
        if len(peer_octets) == 4 and len(octets) == 4:
            if octets[:3] == peer_octets[:3]:
                score += 110
            elif octets[:2] == peer_octets[:2]:
                score += 60

        if addr.is_private:
            if ip_str.startswith("192.168."):
                if ip_str.startswith("192.168.56.") or ip_str.startswith("192.168.137."):
                    score -= 35
                else:
                    score += 30
            elif ip_str.startswith("10."):
                score += 12 if not is_virtual else -20
            else:
                score += 8 if not is_virtual else -30

        if peer_probe_ip == ip_str:
            score += 25
        if inet_probe_ip == ip_str and not is_virtual:
            score += 15

        if score > best_score:
            best_score = score
            best_ip = ip_str

    if best_ip:
        return best_ip

    if peer_probe_ip and _is_valid_host_ip(peer_probe_ip):
        return peer_probe_ip

    try:
        for info in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET):
            cand = info[4][0]
            if _is_valid_host_ip(cand) and ipaddress.IPv4Address(cand) not in cgnat_net and cand.startswith("192.168."):
                return cand
    except Exception:
        pass

    if inet_probe_ip and _is_valid_host_ip(inet_probe_ip):
        return inet_probe_ip

    return "127.0.0.1"

def get_machine_id():
    """Bu Windows kasa bilgisayarina ozgu kalici donanim kimligi uretir."""
    try:
        key = winreg.OpenKey(winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Cryptography", 0, winreg.KEY_READ)
        guid, _ = winreg.QueryValueEx(key, "MachineGuid")
        winreg.CloseKey(key)
        if guid:
            return hashlib.sha1(str(guid).encode("utf-8")).hexdigest()[:12]
    except Exception:
        pass
    return f"{uuid.getnode():012x}"

def _get_deterministic_terminal_id(scale_ip: str = None):
    ip = get_local_ip(scale_ip)
    if ip and ip != "127.0.0.1":
        return "kasa_" + ip.replace(".", "_")
    return f"kasa_{get_machine_id()[:8]}"

def _load_reg_settings() -> dict:
    data = {}
    try:
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, SETTINGS_REG_KEY, 0, winreg.KEY_READ)
        for field in ["server_url", "terminal_id", "terminal_name", "scale_default_ip", "scale_default_port", "user_customized", "restaurant_code", "start_hidden"]:
            try:
                val, _ = winreg.QueryValueEx(key, field)
                if field == "scale_default_port":
                    data[field] = int(val)
                elif field in ("user_customized", "start_hidden"):
                    data[field] = (str(val).lower() == "true")
                else:
                    data[field] = str(val)
            except FileNotFoundError:
                pass
        # Setup kurulum sihirbazının veya uygulama içi ayarların yazdığı başlangıç/bildirim değerleri
        for reg_name, cfg_name in [("AutoStart", "auto_start"), ("ShowNotifications", "show_notifications")]:
            try:
                val, _ = winreg.QueryValueEx(key, reg_name)
                data[cfg_name] = bool(val)
            except FileNotFoundError:
                pass
        winreg.CloseKey(key)
    except Exception:
        pass
    return data

def _save_reg_settings(cfg: dict):
    try:
        key = winreg.CreateKey(winreg.HKEY_CURRENT_USER, SETTINGS_REG_KEY)
        for field in ["server_url", "terminal_id", "terminal_name", "scale_default_ip", "scale_default_port", "user_customized", "restaurant_code", "start_hidden"]:
            if field in cfg and cfg[field] is not None:
                winreg.SetValueEx(key, field, 0, winreg.REG_SZ, str(cfg[field]))
        if "auto_start" in cfg:
            winreg.SetValueEx(key, "AutoStart", 0, winreg.REG_DWORD, 1 if cfg["auto_start"] else 0)
        if "show_notifications" in cfg:
            winreg.SetValueEx(key, "ShowNotifications", 0, winreg.REG_DWORD, 1 if cfg["show_notifications"] else 0)
        winreg.CloseKey(key)
    except Exception:
        pass

def load_config():
    cfg = DEFAULT_CONFIG.copy()
    local_rc = None
    # 1. Önce .exe yanındaki config.json dosyasını oku
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, "r", encoding="utf-8") as f:
                cf = json.load(f)
                cfg.update(cf)
                if cf.get("restaurant_code"):
                    local_rc = cf.get("restaurant_code")
        except Exception:
            pass

    # 2. %APPDATA%\BonCoreAgent\config.json dosyasını oku (Kalıcı kullanıcı ayarları)
    if os.path.exists(APPDATA_CONFIG_FILE):
        try:
            with open(APPDATA_CONFIG_FILE, "r", encoding="utf-8") as f:
                appdata_cfg = json.load(f)
                cfg.update(appdata_cfg)
        except Exception:
            pass

    # 3. Windows Registry'deki kalıcı kullanıcı ayarlarını oku
    reg_cfg = _load_reg_settings()
    if reg_cfg:
        cfg.update(reg_cfg)

    # ZIP paketinden gelen özel restoran kodu varsa önceliklendir
    if local_rc:
        cfg["restaurant_code"] = local_rc

    # 4. Sabit (Deterministik) Terminal ID ata (mevcut geçerli ID'yi IP değişince ezme!)
    scale_ip = cfg.get("scale_default_ip", "192.168.1.150")
    existing_tid = str(cfg.get("terminal_id") or "").strip()
    if not existing_tid or existing_tid == "kasa_127_0_0_1":
        cfg["terminal_id"] = _get_deterministic_terminal_id(scale_ip)

    save_config(cfg)
    return cfg

_CONFIG_LOCK = threading.Lock()

def save_config(cfg):
    with _CONFIG_LOCK:
        try:
            os.makedirs(APPDATA_DIR, exist_ok=True)
            with open(APPDATA_CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(cfg, f, indent=2, ensure_ascii=False)
        except Exception:
            pass
        try:
            with open(CONFIG_FILE, "w", encoding="utf-8") as f:
                json.dump(cfg, f, indent=2, ensure_ascii=False)
        except Exception:
            pass
        _save_reg_settings(cfg)

# --- WINDOWS BAŞLANGIÇ KAYDI (AUTOSTART - GİZLİ BAŞLATMA) ---
REG_PATH = r"Software\Microsoft\Windows\CurrentVersion\Run"
STARTUP_APPROVED_PATH = r"Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\Run"
REG_NAME = "BonCoreAgent"
LEGACY_REG_NAMES = ["BonCoreHardwareAgent"]


def _delete_reg_value_safe(root, subkey, name):
    try:
        key = winreg.OpenKey(root, subkey, 0, winreg.KEY_ALL_ACCESS)
        try:
            winreg.DeleteValue(key, name)
        except FileNotFoundError:
            pass
        finally:
            winreg.CloseKey(key)
    except Exception:
        pass


def _is_boncore_run_command(val) -> bool:
    if not isinstance(val, str):
        return False
    low = val.lower()
    return ("boncoreagent" in low) or ("hardware_agent" in low and "desktop_app.py" in low)


def cleanup_duplicate_autostart():
    """Remove legacy/duplicate BonCore startup registry values so Windows lists at most one entry."""
    for legacy_name in LEGACY_REG_NAMES:
        _delete_reg_value_safe(winreg.HKEY_CURRENT_USER, REG_PATH, legacy_name)
        _delete_reg_value_safe(winreg.HKEY_CURRENT_USER, STARTUP_APPROVED_PATH, legacy_name)
        _delete_reg_value_safe(winreg.HKEY_LOCAL_MACHINE, REG_PATH, legacy_name)
        _delete_reg_value_safe(winreg.HKEY_LOCAL_MACHINE, STARTUP_APPROVED_PATH, legacy_name)

    try:
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_ALL_ACCESS)
        try:
            duplicates = []
            idx = 0
            while True:
                try:
                    name, val, _ = winreg.EnumValue(key, idx)
                    idx += 1
                    if name != REG_NAME and _is_boncore_run_command(val):
                        duplicates.append(name)
                except OSError:
                    break
            for dup in duplicates:
                try:
                    winreg.DeleteValue(key, dup)
                except FileNotFoundError:
                    pass
                _delete_reg_value_safe(winreg.HKEY_CURRENT_USER, STARTUP_APPROVED_PATH, dup)
        finally:
            winreg.CloseKey(key)
    except Exception:
        pass


def set_windows_autostart(enable=True):
    try:
        cleanup_duplicate_autostart()
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_ALL_ACCESS)
        if enable:
            if getattr(sys, 'frozen', False):
                app_path = f'"{sys.executable}" --hidden'
            else:
                app_path = f'"{sys.executable}" "{os.path.abspath(__file__)}" --hidden'
            winreg.SetValueEx(key, REG_NAME, 0, winreg.REG_SZ, app_path)
            winreg.CloseKey(key)
        else:
            winreg.CloseKey(key)
            for name in [REG_NAME] + LEGACY_REG_NAMES:
                _delete_reg_value_safe(winreg.HKEY_CURRENT_USER, REG_PATH, name)
                _delete_reg_value_safe(winreg.HKEY_CURRENT_USER, STARTUP_APPROVED_PATH, name)
                _delete_reg_value_safe(winreg.HKEY_LOCAL_MACHINE, REG_PATH, name)
                _delete_reg_value_safe(winreg.HKEY_LOCAL_MACHINE, STARTUP_APPROVED_PATH, name)
            for startup_dir in [
                os.path.join(os.environ.get("APPDATA", ""), r"Microsoft\Windows\Start Menu\Programs\Startup"),
                os.path.join(os.environ.get("PROGRAMDATA", ""), r"Microsoft\Windows\Start Menu\Programs\Startup"),
            ]:
                for lnk in ("BonCoreAgent.lnk", "BonCore Donanım Köprüsü.lnk", "BonCore Hardware Agent.lnk"):
                    try:
                        p = os.path.join(startup_dir, lnk)
                        if os.path.exists(p):
                            os.remove(p)
                    except Exception:
                        pass
        return True
    except Exception as e:
        print("Autostart reg error:", e)
        return False


def is_windows_autostart():
    try:
        key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, REG_PATH, 0, winreg.KEY_READ)
        try:
            for name in [REG_NAME] + LEGACY_REG_NAMES:
                try:
                    val, _ = winreg.QueryValueEx(key, name)
                    if val:
                        return True
                except FileNotFoundError:
                    pass
        finally:
            winreg.CloseKey(key)
        return False
    except Exception:
        return False

# --- YEREL YAZICILARI LİSTELE VE TERMAL BASKI ---
def get_windows_printers():
    printers = []
    # 1. win32print (Hızlı ve doğrudan)
    try:
        import win32print
        for p in win32print.EnumPrinters(win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS):
            name = p[2]
            if name and name not in printers:
                printers.append(name)
    except Exception:
        pass

    # 2. PowerShell fallback
    if not printers:
        try:
            cmd = ["powershell", "-NoProfile", "-Command", "(Get-Printer).Name"]
            out = subprocess.check_output(cmd, text=True, errors="ignore")
            for line in out.splitlines():
                line = line.strip()
                if line and line not in printers:
                    printers.append(line)
        except Exception:
            pass

    virtual_kw = ("microsoft print to pdf", "microsoft xps", "onenote", "fax", "anydesk printer", "send to onenote")
    printers.sort(key=lambda x: (any(k in x.lower() for k in virtual_kw), x.lower()))
    return printers

def print_slip_to_printer(printer_name: str, raw_text: str) -> bool:
    """
    Termal yazıcıya doğrudan ESC/POS formatında fiş basar ve otomatik kağıt keser.
    """
    tr_map = str.maketrans("çÇğĞıİöÖşŞüÜ", "cCgGiIoOsSuU")
    clean_text = raw_text.translate(tr_map)

    # Sanal Yazıcı Kontrolü (PDF, OneNote, XPS, vb.)
    p_low = printer_name.lower()
    is_virtual = any(v in p_low for v in ["pdf", "onenote", "xps", "fax", "anydesk"])
    if is_virtual:
        try:
            desktop = os.path.join(os.path.expanduser("~"), "Desktop")
            if not os.path.exists(desktop):
                desktop = os.path.expanduser("~")
            preview_file = os.path.join(desktop, "BonCore_Fis_Onizleme.txt")
            with open(preview_file, "w", encoding="utf-8") as f:
                f.write(clean_text)
            try:
                os.startfile(preview_file)
            except Exception:
                pass
            return True
        except Exception as e:
            print(f"Virtual printer preview error: {e}")

    # Satır sonlarını Windows CRLF formatına getir
    clean_text = clean_text.replace("\r\n", "\n").replace("\n", "\r\n")

    # ESC/POS init + metin + Form Feed + kağıt kesme (GS V B 0)
    esc_init = b"\x1b\x40"
    esc_feed = b"\r\n\r\n\r\n\x0c"
    esc_cut = b"\x1d\x56\x42\x00"
    raw_data = esc_init + clean_text.encode("latin-1", errors="replace") + esc_feed + esc_cut

    # 1. win32print RAW Spooler
    try:
        import win32print
        hPrinter = win32print.OpenPrinter(printer_name)
        try:
            hJob = win32print.StartDocPrinter(hPrinter, 1, ("BonCore Adisyon", None, "RAW"))
            try:
                win32print.StartPagePrinter(hPrinter)
                win32print.WritePrinter(hPrinter, raw_data)
                win32print.EndPagePrinter(hPrinter)
            finally:
                win32print.EndDocPrinter(hPrinter)
        finally:
            win32print.ClosePrinter(hPrinter)
        return True
    except Exception as e:
        print(f"win32print error on {printer_name}:", e)

    # 2. Notepad /pt fallback
    try:
        import tempfile
        with tempfile.NamedTemporaryFile("w", encoding="utf-8", delete=False, suffix=".txt") as tf:
            tf.write(clean_text)
            temp_path = tf.name
        subprocess.run(["notepad.exe", "/pt", temp_path, printer_name], timeout=5)
        try:
            os.remove(temp_path)
        except Exception:
            pass
        return True
    except Exception as e:
        print(f"Fallback print error on {printer_name}:", e)
        return False

# --- CAS TERAZİ PARSER & NETWORK ---
def parse_cas_cl3000(raw_bytes: bytes, raw_str: str):
    is_stable = True
    raw_upper = raw_str.upper()
    if "US" in raw_upper or "UNSTABLE" in raw_upper or (" U " in raw_upper) or (raw_upper.startswith("U")):
        is_stable = False
    elif "ST" in raw_upper or "STABLE" in raw_upper or (" S " in raw_upper) or (raw_upper.startswith("S")):
        is_stable = True

    unit = "kg"
    if " g" in raw_str.lower() and "kg" not in raw_str.lower():
        unit = "g"

    match_float = re.search(r'([+-]?\s*\d+\.\d+)', raw_str)
    weight = 0.0
    found = False

    if match_float:
        try:
            val_str = match_float.group(1).replace(" ", "")
            weight = float(val_str)
            if unit == "g":
                weight = round(weight / 1000.0, 3)
            else:
                weight = round(weight, 3)
            found = True
        except Exception:
            pass

    if not found:
        match_int = re.search(r'([+-]?\s*\d{2,})', raw_str)
        if match_int:
            try:
                val_str = match_int.group(1).replace(" ", "")
                val = float(val_str)
                if val >= 50 or unit == "g":
                    weight = round(val / 1000.0, 3)
                else:
                    weight = round(val, 3)
                found = True
            except Exception:
                pass

    if not found and len(raw_bytes) >= 3:
        for i in range(len(raw_bytes) - 2):
            chunk = raw_bytes[i:i+4]
            digits = [chr(b) for b in chunk if 0x30 <= b <= 0x39]
            if len(digits) >= 3:
                try:
                    val = float("".join(digits))
                    weight = round(val / 1000.0, 3)
                    found = True
                    break
                except Exception:
                    pass

    return {
        "weight": max(0.0, weight),
        "grams": int(round(weight * 1000)),
        "unit": "kg",
        "is_stable": is_stable,
        "found": found
    }

def read_from_serial_ports():
    try:
        import serial
        import serial.tools.list_ports
        ports = serial.tools.list_ports.comports()
        for p in ports:
            port_name = p.device
            for baud in [9600, 4800, 19200]:
                try:
                    with serial.Serial(port_name, baud, timeout=0.25) as ser:
                        chunk = ser.read(256)
                        if not chunk:
                            for cmd in [b"W\r", b"W", b"\x05", b"Q\r"]:
                                ser.write(cmd)
                                time.sleep(0.06)
                                chunk = ser.read(256)
                                if chunk:
                                    break
                        if chunk:
                            raw_str = chunk.decode("latin-1", errors="ignore").strip()
                            parsed = parse_cas_cl3000(chunk, raw_str)
                            if parsed.get("found"):
                                return {
                                    "success": True,
                                    "weight": parsed["weight"],
                                    "unit": parsed["unit"],
                                    "grams": parsed["grams"],
                                    "is_stable": parsed["is_stable"],
                                    "raw": raw_str,
                                    "hex": chunk.hex(),
                                    "source": f"Serial ({port_name} @ {baud})",
                                    "ip": port_name,
                                    "port": baud
                                }
                except Exception:
                    pass
    except Exception:
        pass
    return None

def encode_cas_cl_packet(opcode: bytes, address: int = 0, data: bytes = b"") -> bytes:
    buf = bytearray()
    buf.extend(opcode)
    buf.extend(struct.pack("<I", address))
    buf.append(ord(","))
    buf.extend(struct.pack("<H", len(data)))
    buf.append(ord(":"))
    buf.extend(data)
    buf.append(ord(":"))
    ck = sum(buf[2:]) % 256
    buf.append(ck)
    buf.append(0x0D)
    return bytes(buf)

def parse_cas_cl_response(raw_bytes: bytes):
    if not raw_bytes or len(raw_bytes) < 12:
        return None

    idx = raw_bytes.find(b"WN")
    if idx != -1 and len(raw_bytes) >= idx + 40:
        packet = raw_bytes[idx:]
        try:
            scale_id = struct.unpack("<I", packet[2:6])[0]
            data_len = struct.unpack("<H", packet[7:9])[0]
            status_data = packet[10:10+data_len]
            if len(status_data) >= 16:
                load_flag = status_data[0]
                stable_flag = status_data[1]
                unit_code = status_data[4]
                unit_str = "kg" if unit_code == 0 else "lb"
                dec_pt = status_data[5]
                divisor = float(10 ** dec_pt) if 1 <= dec_pt <= 4 else 1000.0
                weight_int = struct.unpack("<i", status_data[12:16])[0]
                weight_kg = round(weight_int / divisor, 3)
                return {
                    "found": True,
                    "weight": max(0.0, weight_kg),
                    "grams": int(round(weight_kg * 1000)),
                    "unit": unit_str,
                    "is_stable": (stable_flag == 1),
                    "load_flag": load_flag,
                    "scale_id": scale_id,
                    "protocol": "CAS-CL-Native-Status (WN)"
                }
        except Exception as e:
            print("CAS CL WN parse error:", e)

    return None

def try_read_from_socket(ip: str, port: int, timeout: float = 1.0):
    sock = None
    all_chunks = []
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(min(timeout, 1.0))
        sock.connect((ip, port))

        sock.settimeout(0.15)
        try:
            chunk = sock.recv(512)
            if chunk:
                all_chunks.append(chunk)
        except Exception:
            pass

        if not all_chunks:
            commands = [
                encode_cas_cl_packet(b"RN", 0),    # CAS CL status inquiry (Scale 0)
                encode_cas_cl_packet(b"RN", 1),    # CAS CL status inquiry (Scale 1 - standard default)
                encode_cas_cl_packet(b"RN", 255),  # CAS CL broadcast
                encode_cas_cl_packet(b"RV", 0),    # CAS CL version ping
                encode_cas_cl_packet(b"RV", 1),
                encode_cas_cl_packet(b"WN", 0),
                encode_cas_cl_packet(b"WN", 1),
                b"W\r\n",
                b"W\r",
                b"\x05",
                b"\x0200RC00\x03",
                b"\x0200W00\x03",
                b"\x02W\x03",
                b"Q\r\n",
                b"S\r\n",
                b"\x0200\x03\r\n"
            ]
            for cmd in commands:
                try:
                    sock.sendall(cmd)
                    time.sleep(0.06)
                    sock.settimeout(0.25)
                    chunk = sock.recv(512)
                    if chunk:
                        all_chunks.append(chunk)
                        if b"WN" in chunk or b"kg" in chunk.lower() or b"g" in chunk.lower():
                            break
                except Exception:
                    continue

        if all_chunks:
            full_raw = b"".join(all_chunks)
            native_res = parse_cas_cl_response(full_raw)
            if native_res and native_res.get("found"):
                return {
                    "success": True,
                    "weight": native_res["weight"],
                    "unit": native_res["unit"],
                    "grams": native_res["grams"],
                    "is_stable": native_res["is_stable"],
                    "raw": f"CAS-WN: {native_res['weight']} {native_res['unit']}",
                    "hex": full_raw.hex(),
                    "source": f"CAS-CL TCP ({ip}:{port})"
                }

            raw_str = full_raw.decode("latin-1", errors="ignore").strip()
            parsed = parse_cas_cl3000(full_raw, raw_str)
            if parsed.get("found"):
                return {
                    "success": True,
                    "weight": parsed["weight"],
                    "unit": parsed["unit"],
                    "grams": parsed["grams"],
                    "is_stable": parsed["is_stable"],
                    "raw": raw_str,
                    "hex": full_raw.hex(),
                    "source": f"Ethernet ({ip}:{port})"
                }
    except Exception:
        pass
    finally:
        if sock:
            try:
                sock.close()
            except Exception:
                pass
    return None

def read_cas_scale(target_ip: str = "192.168.1.150", target_port: int = 2004, timeout: float = 2.0):
    ports_to_try = [target_port]
    for alt_p in [2004, 5000, 4001, 23, 8000]:
        if alt_p not in ports_to_try:
            ports_to_try.append(alt_p)

    for p in ports_to_try:
        res = try_read_from_socket(target_ip, p, timeout=min(timeout, 0.8))
        if res and res.get("success"):
            return res

    serial_res = read_from_serial_ports()
    if serial_res and serial_res.get("success"):
        return serial_res

    # Ağdaki diğer standart CAS IP'leri dene
    base_prefix = target_ip.rsplit(".", 1)[0]
    for last_octet in [150, 151, 152, 200, 100, 20]:
        alt_ip = f"{base_prefix}.{last_octet}"
        if alt_ip != target_ip:
            res = try_read_from_socket(alt_ip, target_port, timeout=0.25)
            if res and res.get("success"):
                return res

    return {
        "success": False,
        "error": f"CAS CL-3000 terazisine ulaşılamadı ({target_ip}:{target_port}).",
        "weight": 0.0,
        "grams": 0,
        "unit": "kg",
        "is_stable": False
    }

def ping_scale_tcp(ip: str, port: int = 2004, timeout: float = 1.0) -> bool:
    sock = None
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        sock.connect((ip, port))
        return True
    except Exception:
        return False
    finally:
        if sock:
            try:
                sock.close()
            except Exception:
                pass

# --- TRAY ICON OLUŞTURUCU ---
def create_tray_image(status="connected"):
    """
    Sistem tepsisi (System Tray) icin BonCore kurumsal logosunu ve
    sag alttaki BonCore.Nokta durum rozetini hazirlar:
      - 'connected' (veya True): Yeşil nokta (Siteye bağlı)
      - 'connecting' / 'yellow': Sarı nokta (Bağlanmaya çalışıyor)
      - 'disconnected' (veya False): Kırmızı nokta (Bağlantı kesildi veya bağlanılamıyor)
    """
    width, height = 64, 64
    base_logo = get_app_logo_image(width, height)

    # Sag alt koseye canli durum rozeti (badge) ekle
    draw = ImageDraw.Draw(base_logo)
    if status in ("connected", True):
        dot_color = (16, 185, 129, 255)   # Canlı Zümrüt Yeşili (#10b981)
    elif status in ("connecting", "yellow"):
        dot_color = (245, 158, 11, 255)  # Canlı Kehribar Sarısı (#f59e0b)
    else:
        dot_color = (239, 68, 68, 255)   # Canlı Kırmızı (#ef4444)

    border_color = (255, 255, 255, 255)

    # 18px capinda gosterge noktasi ve beyaz kontrast cercevesi
    x1, y1 = 44, 44
    x2, y2 = 62, 62
    draw.ellipse([(x1 - 2, y1 - 2), (x2 + 2, y2 + 2)], fill=border_color)
    draw.ellipse([(x1, y1), (x2, y2)], fill=dot_color)

    return base_logo

# --- TEK KOPYA & IPC HABERLEŞMESİ ---
def check_single_instance_or_signal():
    """
    Eğer uygulama zaten arka planda çalışıyorsa:
    --hidden parametresi ile geldiyse sessizce kapanır.
    Masaüstünden normal tıklandıysa çalışan kopyaya 'SHOW' sinyali gönderip pencereyi öne çıkarır.
    """
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        s.bind(('127.0.0.1', IPC_PORT))
        s.listen(2)
        return s
    except OSError:
        is_hidden = any(arg in sys.argv for arg in ["--hidden", "--minimized", "-h"])
        if not is_hidden:
            try:
                sender = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sender.connect(('127.0.0.1', IPC_PORT))
                sender.sendall(b"SHOW\n")
                sender.close()
            except Exception:
                pass
        sys.exit(0)

def start_ipc_listener(ipc_socket, callback_show):
    def _listen():
        while True:
            try:
                conn, _ = ipc_socket.accept()
                data = conn.recv(64)
                if b"SHOW" in data:
                    callback_show()
                conn.close()
            except Exception:
                break
    t = threading.Thread(target=_listen, daemon=True)
    t.start()


